1	package components
2	
3	import (
4		"strings"
5		"testing"
6	
7		"github.com/charmbracelet/x/ansi"
8	)
9	
10	var (
11		errA = FieldError{Key: "a", Text: "A bad"}
12		errB = FieldError{Key: "b", Text: "B bad"}
13		errC = FieldError{Key: "c", Text: "C bad"}
14	)
15	
16	func TestValidationZeroValueSaysNothing(t *testing.T) {
17		var v Validation
18		if v.Status() != (Status{}) {
19			t.Errorf("zero Validation Status = %+v, want zero", v.Status())
20		}
21		if v.Invalid("x") {
22			t.Error("zero Validation reports x invalid")
23		}
24	}
25	
26	// Nothing is validated before the first submit: no field is flagged while the
27	// user is still typing the form for the first time.
28	func TestValidationRevalidateBeforeSubmitIsInert(t *testing.T) {
29		var v Validation
30		v.Revalidate([]FieldError{errA})
31		if v.Invalid("a") || v.Status() != (Status{}) {
32			t.Errorf("Revalidate before Submit flagged a field: invalid=%v status=%+v", v.Invalid("a"), v.Status())
33		}
34	}
35	
36	func TestValidationSubmit(t *testing.T) {
37		tests := []struct {
38			name        string
39			errs        []FieldError
40			wantOK      bool
41			wantText    string
42			wantInvalid []string
43			wantValid   []string
44		}{
45			{"no errors", nil, true, "", nil, []string{"a", "b"}},
46			{"one error", []FieldError{errA}, false, "A bad", []string{"a"}, []string{"b"}},
47			{"two errors", []FieldError{errA, errB}, false, "A bad (+1 more)", []string{"a", "b"}, nil},
48			{"three errors", []FieldError{errA, errB, errC}, false, "A bad (+2 more)", []string{"a", "b", "c"}, nil},
49			{"first in display order wins", []FieldError{errB, errA}, false, "B bad (+1 more)", []string{"a", "b"}, nil},
50		}
51		for _, tt := range tests {
52			t.Run(tt.name, func(t *testing.T) {
53				var v Validation
54				if got := v.Submit(tt.errs); got != tt.wantOK {
55					t.Errorf("Submit() = %v, want %v", got, tt.wantOK)
56				}
57				st := v.Status()
58				if st.Text != tt.wantText {
59					t.Errorf("Status().Text = %q, want %q", st.Text, tt.wantText)
60				}
61				if tt.wantText != "" && st.Level != LevelError {
62					t.Errorf("Status().Level = %v, want LevelError", st.Level)
63				}
64				for _, k := range tt.wantInvalid {
65					if !v.Invalid(k) {
66						t.Errorf("Invalid(%q) = false, want true", k)
67					}
68				}
69				for _, k := range tt.wantValid {
70					if v.Invalid(k) {
71						t.Errorf("Invalid(%q) = true, want false", k)
72					}
73				}
74			})
75		}
76	}
77	
78	// After a refused submit every change revalidates the whole form: a corrected
79	// field is no longer invalid at the next render, a newly broken one is.
80	func TestValidationRevalidatesAfterARefusedSubmit(t *testing.T) {
81		var v Validation
82		v.Submit([]FieldError{errA, errB})
83	
84		v.Revalidate([]FieldError{errB})
85		if v.Invalid("a") {
86			t.Error("a was corrected but is still invalid")
87		}
88		if !v.Invalid("b") {
89			t.Error("b is still wrong but is not invalid")
90		}
91		if got := v.Status().Text; got != "B bad" {
92			t.Errorf("Status().Text = %q, want %q (no suffix once one error is left)", got, "B bad")
93		}
94	
95		v.Revalidate([]FieldError{errC})
96		if !v.Invalid("c") || v.Invalid("b") {
97			t.Errorf("revalidation did not follow the new errors: c=%v b=%v", v.Invalid("c"), v.Invalid("b"))
98		}
99	
100		v.Revalidate(nil)
101		if v.Invalid("c") || v.Status() != (Status{}) {
102			t.Errorf("Revalidate(nil) left state: invalid=%v status=%+v", v.Invalid("c"), v.Status())
103		}
104	}
105	
106	// A form that revalidates to clean stays attempted: a later error shows at once.
107	func TestValidationStaysLiveAfterItWentClean(t *testing.T) {
108		var v Validation
109		v.Submit([]FieldError{errA})
110		v.Revalidate(nil)
111		v.Revalidate([]FieldError{errA})
112		if !v.Invalid("a") {
113			t.Error("validation went inert after a clean revalidation")
114		}
115	}
116	
117	// A successful submit keeps nothing: a form refused earlier and then accepted
118	// has no error left.
119	func TestValidationSuccessfulSubmitClearsErrors(t *testing.T) {
120		var v Validation
121		v.Submit([]FieldError{errA})
122		if !v.Submit(nil) {
123			t.Fatal("Submit(nil) refused")
124		}
125		if v.Invalid("a") || v.Status() != (Status{}) {
126			t.Error("errors survived an accepted submit")
127		}
128	}
129	
130	// The status is derived, not a timed message: it is recomputed on every call,
131	// is an Error, and the footer still shows it after the 3 s expiry has fired.
132	func TestValidationStatusIsDerivedAndNeverExpires(t *testing.T) {
133		var v Validation
134		v.Submit([]FieldError{errA})
135	
136		var f FooterMessage
137		f.Error("some earlier failure")
138		f.Handle(ClearFooterMsg{ID: f.ID()})
139		if f.IsSet() {
140			t.Fatal("test setup: the timed message should have expired")
141		}
142	
143		out := ansi.Strip(f.View(80, v.Status()))
144		if !strings.Contains(out, "A bad") {
145			t.Fatalf("footer after expiry = %q, want it to still show %q", out, "A bad")
146		}
147		if got := v.Status(); got.Level != LevelError || got.Text != "A bad" {
148			t.Errorf("Status() = %+v, want the same error on every call", got)
149		}
150	
151		v.Revalidate([]FieldError{errB})
152		out = ansi.Strip(f.View(80, v.Status()))
153		if strings.Contains(out, "A bad") || !strings.Contains(out, "B bad") {
154			t.Errorf("footer = %q, want it recomputed to %q", out, "B bad")
155		}
156	}
